<script setup>
import {ref,shallowRef,onMounted,onBeforeUnmount,computed} from 'vue';
import {Button,Cell,CellGroup,Field,Checkbox,Popup,Picker,Uploader} from 'vant';
import 'vant/es/button/style';
import 'vant/es/cell/style';
import 'vant/es/cell-group/style';
import 'vant/es/field/style';
import 'vant/es/checkbox/style';
import 'vant/es/popup/style';
import 'vant/es/picker/style';
import 'vant/es/uploader/style';
const {controller}=defineProps({controller:{type:Object,required:true}}),model=shallowRef(controller.snapshot()),actions=controller.actions;
const canvas=ref(),picker=ref('');
const unsubscribe=controller.subscribe(value=>model.value=value);
const columns=computed(()=>picker.value==='task'?[...model.value.tasks.map(t=>({text:t.title,value:t.id})),{text:'自拟题目 / 老师布置的作业',value:'custom'}]:[{text:'细',value:2},{text:'中',value:4},{text:'粗',value:7}]);
function picked({selectedValues}){const value=selectedValues[0];if(picker.value==='task')actions.chooseTask(value);else actions.setWidth(value);picker.value='';}
onMounted(()=>{if(canvas.value)actions.attachCanvas(canvas.value);});
onBeforeUnmount(()=>{unsubscribe();actions.attachCanvas(null);});
const photo=files=>{const file=(Array.isArray(files)?files[0]:files)?.file;return actions.photo(file);};
</script>
<template>
 <main class="student-handwriting">
  <nav aria-label="页面导航"><Button tag="a" :href="model.backHref">← 返回课堂</Button></nav>
  <header><p class="eyebrow">GROWING · 真实书写</p><h1>{{model.title}}</h1><p>{{model.courseLabel}}</p><p>{{model.guide}}</p></header>
  <p v-if="model.kind==='error'" role="status">{{model.error}}</p>
  <section v-else class="editor panel">
   <section class="task-bank"><h2>{{model.essay?'本单元写作题目':'本章解答题'}}</h2><label>选择题目</label><Cell :value="model.tasks.find(t=>t.id===model.task)?.title||'自拟题目'" is-link :clickable="!model.busy&&!model.importing&&!model.application" @click="!model.busy&&!model.importing&&!model.application&&(picker='task')"/></section><Field :model-value="model.prompt" @update:model-value="actions.setPrompt" type="textarea" rows="7" maxlength="6000" :disabled="model.locked||model.application" :label="model.essay?'作文要求':'解答题题目与作答要求'" placeholder="填写完整题目与作答要求"/>
   <p v-if="model.knowledge" class="student-writing-knowledge">考核知识点：{{model.knowledge}}</p>
   <section class="student-writing-tools" aria-label="书写工具">
    <Button :type="model.tool==='pen'?'primary':'default'" :aria-pressed="model.tool==='pen'" :disabled="model.locked" @click="actions.setTool('pen')">钢笔</Button><Button :type="model.tool==='eraser'?'primary':'default'" :aria-pressed="model.tool==='eraser'" :disabled="model.locked" @click="actions.setTool('eraser')">橡皮</Button><Button :disabled="model.locked" @click="picker='width'">笔宽：{{({2:'细',4:'中',7:'粗'})[model.width]}}</Button><Button :disabled="model.locked||!model.canUndo" @click="actions.undo">撤销</Button><Button :disabled="model.locked||!model.canRedo" @click="actions.redo">重做</Button><Checkbox :model-value="model.finger" @update:model-value="actions.setFinger" :disabled="model.locked">允许手指书写</Checkbox>
   </section>
   <nav class="student-writing-pages" aria-label="原稿页码"><Button aria-label="上一页" icon="arrow-left" :disabled="model.locked||model.page===0" @click="actions.turn(model.page-1)"/><span>第 {{model.page+1}} / {{model.pageCount}} 页</span><Button aria-label="下一页" icon="arrow" :disabled="model.locked||model.page===model.pageCount-1" @click="actions.turn(model.page+1)"/><Button :disabled="model.locked||model.pageCount>=8" icon="plus" aria-label="加一页" @click="actions.addPage">加一页</Button></nav>
   <p class="muted">默认只接收手写笔和鼠标，忽略手指误触。需要移动页面时，请在纸张外滑动。</p><div class="student-writing-paper"><canvas ref="canvas" width="800" height="1100" aria-label="手写作答纸，支持手写笔和鼠标" @pointerdown="actions.pointerDown" @pointermove="actions.pointerMove" @pointerup="actions.pointerEnd" @pointercancel="actions.pointerEnd" @lostpointercapture="actions.pointerEnd">需要支持 Canvas 的浏览器。</canvas></div>
   <p class="student-writing-status" role="status" aria-live="polite">{{model.saveStatus}}</p>
   <div class="student-writing-actions"><Button :disabled="model.locked" @click="actions.save">立即保存原稿</Button><Button type="primary" :disabled="model.locked" :loading="model.busy" loading-text="正在批改" @click="actions.grade">AI批改</Button><Uploader accept="image/*" capture="environment" :after-read="photo" :show-upload-list="false" :disabled="model.locked"><Button :disabled="model.locked" :loading="model.importing">拍照解答</Button></Uploader><Button v-if="model.busy" @click="actions.cancel">取消批改</Button></div>
   <p class="student-writing-status" role="status" aria-live="polite">{{model.status}}</p>
   <section v-if="model.grades.length" class="student-writing-grades" aria-label="原稿批改记录"><article v-for="(grade,index) in model.grades" :key="grade.at+':'+index"><h2>{{grade.current?'本份原稿':'历史点评 · 原稿已修改'}}</h2><p class="student-writing-score">{{grade.needsReview?'需要复核 · 不计分':grade.score+' / 100'}}</p><p v-if="grade.parts">{{grade.parts.map((part,i)=>(model.essay?['内容','结构','语言','标点与格式']:['审题','思路','推导','表达'])[i]+' '+part+'/'+(model.essay?[25,20,35,20]:[20,30,30,20])[i]).join(' · ')}}</p><p :class="{'assessment-gap':grade.needsReview||grade.score<80}">{{grade.feedback}}</p><div v-html="grade.details"/><small>{{grade.at.slice(0,19).replace('T',' ')}} · {{grade.source==='handwriting'?'直接查看手写原稿':'历史文字点评'}}</small></article></section>
  </section>
  <Popup :show="!!picker" @update:show="value=>!value&&(picker='')" position="bottom" round class="student-writing-picker"><header><h2>{{picker==='task'?'选择题目':'选择笔宽'}}</h2><Button icon="cross" aria-label="关闭选择" @click="picker=''"/></header><Picker :columns="columns" :model-value="[picker==='task'?model.task:model.width]" confirm-button-text="选择" :cancel-button-text="''" @confirm="picked"/></Popup>
 </main>
</template>
<style scoped>
.student-handwriting{--van-primary-color:#22634b;color:#24352e;max-width:1080px;padding:24px clamp(16px,4vw,36px) 60px;margin:0 auto;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif}.student-handwriting,.student-handwriting :deep(*){box-sizing:border-box}.student-handwriting :deep(.van-button){font:inherit;min-height:44px;text-decoration:none}.student-handwriting header{padding:24px 0 18px}.student-handwriting h1{font-size:clamp(26px,4vw,36px);margin:0 0 14px;line-height:1.35}.student-handwriting header p{font-size:14px;color:#64746b;line-height:1.8;margin:0 0 12px}.student-handwriting :deep(.van-cell-group--inset){margin:0;border:1px solid #dce4dc;border-radius:12px;overflow:hidden}.student-handwriting :deep(.van-cell){padding:16px}.student-handwriting :deep(.van-field__label){width:65px}.student-handwriting :deep(.van-field__control){border:0;background:transparent;padding:0;min-height:0;font:inherit;box-shadow:none}.student-writing-knowledge{font-size:14px;line-height:1.8;color:#64746b}.student-writing-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:20px 0}.student-writing-tools :deep(.van-checkbox){min-height:44px;margin-left:6px}.student-writing-pages{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.student-writing-pages span{font-size:14px}.student-writing-paper{max-width:800px;margin:0 auto;border:1px solid #dce4dc;border-radius:8px;overflow:hidden;background:#fff}.student-writing-paper canvas{display:block;width:100%;height:auto;touch-action:none;background:repeating-linear-gradient(#fff 0px,#fff 39px,#e8ece9 40px)}.student-writing-actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.student-writing-status{font-size:14px;line-height:1.8;overflow-wrap:anywhere}.student-writing-grades article{padding:22px 0;border-top:1px solid #dce4dc;line-height:1.8;overflow-wrap:anywhere}.student-writing-grades h2{font-size:18px}.student-writing-grades :deep(a){color:#22634b}.student-writing-score{font-size:24px;font-weight:600}.student-writing-picker{color:#24352e;max-height:85dvh;--van-primary-color:#22634b}.student-writing-picker header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px}.student-writing-picker h2{font-size:18px;margin:0}.student-writing-picker :deep(.van-button){width:44px;height:44px;padding:0}.student-writing-picker :deep(.van-picker__cancel){display:none}.student-writing-picker :deep(.van-picker__confirm){min-height:44px}.student-handwriting a:focus-visible{outline:3px solid #22634b;outline-offset:3px}


.student-handwriting{max-width:1340px;padding:24px;color:var(--ui-ink);font:15px/1.7 system-ui,"Microsoft YaHei",sans-serif;--van-primary-color:var(--ui-accent)}.student-handwriting>nav :deep(.van-button){border:0;background:transparent;padding:0;color:var(--ui-accent);text-decoration:underline}.student-handwriting>nav :deep(.van-icon){display:none}.student-handwriting header{padding:8px 0 20px}.student-handwriting header .eyebrow{font-size:12px;letter-spacing:.04em;margin:0 0 12px}.student-handwriting header h1{font-size:26px;line-height:1.4;font-weight:600;margin:8px 0}.student-handwriting header p{font-size:15px;line-height:1.7;color:inherit;margin:15px 0}.student-handwriting .editor{background:var(--ui-surface);border:1px solid var(--ui-line);border-radius:12px;padding:22px}.student-handwriting :deep(.van-cell){font:inherit;color:inherit}.student-handwriting .task-bank{margin-bottom:24px;padding-bottom:30px;border-bottom:1px solid var(--ui-line)}.student-handwriting :deep(.van-cell__value){text-align:left;color:inherit}.student-handwriting :deep(.van-field__control:disabled){color:inherit;-webkit-text-fill-color:currentColor;opacity:1}.task-bank h2{font-size:20px;margin:0 0 14px}.task-bank>label{display:block;font-weight:600;margin-bottom:8px}.task-bank :deep(.van-cell){border:1px solid var(--ui-control);border-radius:8px;padding:10px 16px;background:#fffef9}.student-handwriting :deep(.van-field){padding:0;display:flex;flex-direction:column;background:transparent}.student-handwriting :deep(.van-field__label){font-weight:600;width:auto;margin-bottom:8px}.student-handwriting :deep(.van-field__control){display:block;border:1px solid var(--ui-control);border-radius:8px;padding:10px;background:white;color:inherit;line-height:1.8;min-height:210px}.student-writing-tools{gap:8px;margin:12px 0}.student-handwriting :deep(.van-button){padding:7px 13px;min-height:44px;font:inherit;height:auto;border:1px solid #c1cec2;border-radius:8px;color:inherit;background:#fffef9}.student-handwriting :deep(.van-button--primary),.student-writing-tools :deep([aria-pressed=true]){background:var(--ui-accent);color:white}.student-writing-pages{gap:8px;margin:12px 0}.student-writing-tools :deep(.van-checkbox){margin-left:4px}.student-writing-paper{max-width:none;margin:0;border-radius:0;border:1px solid var(--ui-line)}.student-writing-paper canvas{background:repeating-linear-gradient(white 0,white 39px,#e5ecea 40px)}.student-writing-knowledge{margin:12px 0}.student-writing-grades article{background:#f0f4ec;padding:16px;border-radius:12px;margin:12px 0}.student-writing-picker :deep(.van-button){width:44px;height:44px;padding:0}
@media(max-width:850px){.student-handwriting{padding:14px}.student-handwriting .editor{padding:16px}}

</style>
